def compute(vars):
    debt_obligations = vars["v1"]
    purchase_obligations = vars["v2"]
    difference = debt_obligations - purchase_obligations

    return {
        "value": difference,
        "trace": {
            "debt_obligations": debt_obligations,
            "purchase_obligations": purchase_obligations,
            "difference": difference,
            "output_meta": {
                "currency": "$",
                "scale": "thousands",
                "unit": "monetary"
            }
        }
    }
